def _send_false_to_ping(self) -> bool:
        """determine if aiomysql has deprecated, changed the default of,
        or removed the 'reconnect' argument of connection.ping().

        See #13306 and #10492

        """  # noqa: E501

        try:
            Connection = __import__(
                "aiomysql.connection"
            ).connection.Connection
